# Test Case 1: Diagonal pattern x + y = 0 (mod 3)
k1 = 3
count1 = 0
for x in range(N):
    for y in range(N):
        if (x + y) % k1 == 0:
            count1 += 1

# Test Case 2: Single modulus x = 0 (mod 4)
k2 = 4
count2 = 0
for x in range(N):
    for y in range(N):
        if x % k2 == 0:
            count2 += 1

# Test Case 3: Double modulus x = 0 (mod 4) and y = 0 (mod 4)
k3 = 4
l3 = 4
count3 = 0
for x in range(N):
    for y in range(N):
        if x % k3 == 0 and y % l3 == 0:
            count3 += 1

print(f"Test Case 1 (x+y mod 3 == 0): {count1}")
print(f"Test Case 2 (x mod 4 == 0): {count2}")
print(f"Test Case 3 (x mod 4 == 0 and y mod 4 == 0): {count3}")

